import { useCallback, useEffect, useRef, useState } from 'react';
import { requestAssistantSpeech } from './assistantApi';

const languageTag = { uz: 'uz-UZ', ru: 'ru-RU', en: 'en-US' };

export function spokenText(value, language = 'uz') {
  const university = language === 'ru' ? 'Ферганский государственный технический университет'
    : language === 'en' ? 'Fergana State Technical University'
      : 'Farg‘ona davlat texnika universiteti';
  let result = String(value).replace(/```[\s\S]*?```/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[*#_`]/g, '').replace(/\bFSTU\b/gi, university).replace(/\bHEMIS\b/gi, 'Hemis');
  if (language === 'uz') result = result.replace(/[ʻʼ‘’`']/g, '’').replace(/([og])’/gi, '$1‘');
  return result.replace(/\s+/g, ' ').trim();
}
export const spokenUzbek = (value) => spokenText(value, 'uz');

export function splitSpeechText(input, limit = 3500) {
  const chunks = [];
  let rest = input.trim();
  while (rest.length > limit) {
    const prefix = rest.slice(0, limit + 1);
    const ends = [...prefix.matchAll(/[.!?](?=\s)/g)];
    let boundary = ends.length ? ends[ends.length - 1].index + 1 : 0;
    if (boundary < limit / 2) boundary = prefix.lastIndexOf(' ', limit);
    if (boundary < 1) boundary = limit;
    chunks.push(rest.slice(0, boundary).trim());
    rest = rest.slice(boundary).trim();
  }
  if (rest) chunks.push(rest);
  return chunks;
}

export function chooseBrowserVoice(voices, language) {
  const tag = languageTag[language] || languageTag.uz;
  const matching = voices.filter(voice => voice.lang?.toLowerCase().startsWith(tag.slice(0, 2).toLowerCase()));
  return matching.find(voice => /madina|svetlana|jenny|zira|samantha|female|ayol/i.test(voice.name || '')) || matching[0];
}

export default function useUzbekSpeech({ muted, onStateChange, language = 'uz' }) {
  const [notice, setNotice] = useState('');
  const audioRef = useRef(null);
  const urlRef = useRef(null);
  const requestRef = useRef(null);
  const generationRef = useRef(0);
  const aliveRef = useRef(true);
  const playbackDoneRef = useRef(null);

  const stop = useCallback(() => {
    generationRef.current += 1;
    playbackDoneRef.current?.();
    playbackDoneRef.current = null;
    requestRef.current?.abort();
    requestRef.current = null;
    if (audioRef.current) {
      audioRef.current.onplaying = audioRef.current.onended = audioRef.current.onerror = null;
      audioRef.current.pause();
      audioRef.current.removeAttribute('src');
      audioRef.current = null;
    }
    if (urlRef.current) { URL.revokeObjectURL(urlRef.current); urlRef.current = null; }
    window.speechSynthesis?.cancel();
  }, []);

  useEffect(() => {
    aliveRef.current = true;
    return () => { aliveRef.current = false; stop(); };
  }, [stop]);

  useEffect(() => { if (muted) stop(); }, [muted, stop]);

  const speak = useCallback(async (value, greeting = false) => {
    stop();
    const input = spokenText(value, language).slice(0, 20000);
    if (muted || !input || !aliveRef.current) { onStateChange('idle'); return; }
    setNotice('');
    const generation = generationRef.current;
    const isCurrent = () => aliveRef.current && generationRef.current === generation;
    onStateChange(greeting ? 'waving' : 'preparing');

    const browserVoice = (remainingText) => {
      if (!isCurrent()) return;
      const tag = languageTag[language] || languageTag.uz;
      const voice = chooseBrowserVoice(window.speechSynthesis?.getVoices?.() || [], language);
      if (!voice || !window.SpeechSynthesisUtterance) {
        setNotice(language === 'ru' ? 'Не удалось подключиться к голосовому серверу.' : language === 'en' ? 'Could not connect to the voice server.' : 'Ovoz serveriga ulanib bo‘lmadi. «Javobni tinglash» tugmasi orqali qayta urinib ko‘ring.');
        onStateChange('idle');
        return;
      }
      const utterance = new window.SpeechSynthesisUtterance(remainingText);
      utterance.voice = voice;
      utterance.lang = tag;
      utterance.rate = 1;
      utterance.pitch = 1;
      utterance.onstart = () => { if (isCurrent()) onStateChange('talking'); };
      utterance.onend = () => { if (isCurrent()) onStateChange('idle'); };
      utterance.onerror = () => {
        if (isCurrent()) { setNotice('Ovozni ijro etib bo‘lmadi. Javobni matn shaklida o‘qishingiz mumkin.'); onStateChange('idle'); }
      };
      window.speechSynthesis.speak(utterance);
    };

    const controller = new AbortController();
    requestRef.current = controller;
    const segments = splitSpeechText(input);
    const prepare = async (segment) => {
      const timeout = setTimeout(() => controller.abort(), 35000);
      try {
        const response = await requestAssistantSpeech({ text: segment, language, signal: controller.signal });
        if (!response.ok || !response.headers?.get('content-type')?.startsWith('audio/')) throw new Error('voice-unavailable');
        return { blob: await response.blob() };
      } catch (error) { return { error }; }
      finally { clearTimeout(timeout); }
    };
    let segmentIndex = 0;
    try {
      let prepared = prepare(segments[0]);
      for (; segmentIndex < segments.length; segmentIndex += 1) {
        const result = await prepared;
        if (!isCurrent()) return;
        if (result.error) throw result.error;
        // Prepare the next paragraph while this audio plays, without splitting words into separate utterances.
        prepared = segmentIndex + 1 < segments.length ? prepare(segments[segmentIndex + 1]) : null;
        const url = URL.createObjectURL(result.blob);
        urlRef.current = url;
        const audio = new Audio(url);
        audioRef.current = audio;
        audio.preload = 'auto';
        audio.playbackRate = 1;
        audio.volume = 1;
        await new Promise((resolve, reject) => {
          playbackDoneRef.current = resolve;
          audio.onplaying = () => { if (isCurrent()) onStateChange('talking'); };
          audio.onended = resolve;
          audio.onerror = () => reject(new Error('audio-playback-failed'));
          Promise.resolve(audio.play()).catch(reject);
        });
        if (!isCurrent()) return;
        playbackDoneRef.current = null;
        audio.onplaying = audio.onended = audio.onerror = null;
        audio.removeAttribute('src');
        audioRef.current = null;
        URL.revokeObjectURL(url);
        urlRef.current = null;
      }
      if (isCurrent()) onStateChange('idle');
    } catch {
      if (!isCurrent()) return;
      if (audioRef.current) {
        stop();
        setNotice('Ovozni yoqish uchun «Javobni tinglash» tugmasini bosing.');
        onStateChange('idle');
      } else browserVoice(segments.slice(segmentIndex).join(' '));
    }
  }, [language, muted, onStateChange, stop]);

  return { speak, stop, notice };
}
